import{memoryCloudDatabase}from'./cloud-database.ts';import{createCompanyStore}from'../../cloud/company/store.ts';import{executeCompany}from'../../cloud/company/core.ts';
export const COMPANY_NOW=new Date('2026-11-13T12:00:00Z');
export async function companyFixture(){const fixture=memoryCloudDatabase({direct:true}),store=createCompanyStore(fixture.db),owner={owner:true};const run=(actor:any,b:any,clock=COMPANY_NOW)=>store.run(t=>executeCompany(t,actor,b,clock));const company=(await run(owner,{action:'company.create',name:'周期报表测试'})).company;for(const[login,roles]of[['staff',['employee']],['manager',['supervisor']],['leader',['leader']],['other',['employee']]])await run(owner,{action:'member.save',companyId:company.id,login,name:login,roles,active:true});let project=(await run(owner,{action:'project.create',companyId:company.id,name:'项目甲',ownerLogin:'staff',reviewerLogin:'manager',participants:['staff']})).project;const staff={companyId:company.id,login:'staff'},manager={companyId:company.id,login:'manager'},leader={companyId:company.id,login:'leader'},other={companyId:company.id,login:'other'};project=(await run(staff,{action:'project.save',companyId:company.id,id:project.id,version:project.version,progress:35,achievement:'完成样品',risk:'等待验收',next:'交付'},new Date('2026-11-10T08:00:00Z'))).project;project=(await run(staff,{action:'project.submit',companyId:company.id,id:project.id,version:project.version},new Date('2026-11-10T09:00:00Z'))).project;project=(await run(manager,{action:'project.approve',companyId:company.id,id:project.id,version:project.version,comment:'确认'},new Date('2026-11-10T10:00:00Z'))).project;return{fixture,store,run,company,project,owner,staff,manager,leader,other};}
